  Serial.print(",\"Temperature\":");
  Serial.print(myTemp.currentTemp, 2);
  Serial.print(",\"Temperature Target\":");
  Serial.print(myTemp.targetTemp, 2);
  Serial.print(",\"OD\":");
  Serial.print(myOD.nOD, 4);
  Serial.println("}");
}

